// Pure shaping only. No network calls, no credentials here.
// Input: the ClickUp task object returned by the 'Fetch ClickUp Task' node.
// Output: one labeled context object the next iteration / the LLM step will consume.
//
// v1 CORE: this only shapes the CURRENT task. ancestor_chain and
// linked_doc_leaves are intentional stubs that later increments populate
// (the parent-walk loop fills ancestor_chain; doc-link resolution fills
// linked_doc_leaves).

const task = $input.first().json;

return [
  {
    json: {
      current_task: {
        id: task.id,
        name: task.name,
        // ClickUp returns both `description` (plain) and `markdown_description`.
        // Using plain description per spec; swap if you want markdown later.
        description: task.description || ""
      },
      ancestor_chain: [],        // stub — filled by the parent-walk loop (next increment)
      linked_doc_leaves: []      // stub — filled by doc-link resolution (later increment)
    }
  }
];
